#!/usr/bin/env python3
"""Turn 35 Wave 68: THE CLUB CUSTOMISATION LAYER - the official 11-layer kit template map,
the customisation screen's five tabs, the kit-import technical rules, the manager customisation
surface - and a DEFINITIVE DOCUMENTED NEGATIVE on wages.

Wave 68's centrepiece is the official kit-template layer map from the FTG support portal,
which is the single most actionable customisation fact in the corpus: it tells you exactly
which regions of a 512x512 PNG map to which part of the shirt, and that a logo absent from
the PNG simply will not display.

The wages negative closes the corpus's last true zero: there is no wage bill in DLS26.
"""
import json, os, datetime
ROOT='/home/user/dls26-omega'
EVIDENCE_INDEX=os.path.join(ROOT,'docs/continuity/a7e23a6b/evidence/index.jsonl')
CLAIMS_PATH=os.path.join(ROOT,'kb/claims.jsonl')
RAW_DIR=os.path.join(ROOT,'evidence/raw','turn35_w68')

last_ev=max(int(json.loads(l)['evidence_id'].split('-')[1]) for l in open(EVIDENCE_INDEX) if l.strip() and json.loads(l)['evidence_id'].startswith('EV-'))
last_cl=max(int(json.loads(l)['claim_id'].split('-')[1]) for l in open(CLAIMS_PATH) if l.strip() and json.loads(l)['claim_id'].startswith('CLAIM-'))
ev_id=last_ev+1; cl_id=last_cl+1

def new_ev(origin, summary, artifact_path, vol, quality="community"):
    global ev_id
    eid=f'EV-{ev_id:03d}'
    rec={"evidence_id":eid,"parent_claim_id":None,"captured_at":datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'),
         "origin_method":origin,"artifact_path":artifact_path,"volume_label":vol,"source_quality":quality,"summary":summary}
    with open(EVIDENCE_INDEX,'a') as f: f.write(json.dumps(rec)+'\n')
    ev_id+=1; return eid

def add_claim(text, conf, domain, evs, notes=""):
    global cl_id
    cid=f'CLAIM-{cl_id:04d}'
    rec={"claim_id":cid,"text":text,"confidence":conf,"domain":domain,"supporting_evidence":evs,"audit_status":"unchecked","notes":notes}
    with open(CLAIMS_PATH,'a') as f: f.write(json.dumps(rec)+'\n')
    cl_id+=1; return cid

os.makedirs(RAW_DIR,exist_ok=True)

e_cust=new_ev("bluestacks DLS26 custom-kits guide (the full customisation screen walkthrough), FTG support 214422145 'How do I customise my kit / logo in Dream League Soccer' (the official 11-layer template map), gamingtubebd (17 Aug 2026, the MY CLUB > CUSTOMISE path and the Custom Logo / Custom Kit buttons), r/DreamLeagueSoccer 1kwvcy5 (27 May 2025, the edit-host-paste-URL workflow), alibaba custom DLS printing guide (20 Jul 2026, the four-kit claim and the layer-separation rules), dlskits.org (6 Oct 2026) and dlslogo.com / footylogos.com (the 512x512 standard), toucharcade DLS custom-kits forum thread (the legacy text-format kit spec), mytour.vn (the per-jersey colour elements), App Store / Google Play / APKMirror DLS26 (manager customisation and Manager Accessories), thesoccerera DLS26 features (Manager Customisation), fifaworldcupnews (23 Jul 2026, the August kit-and-sponsor update and the July/August chronology), r/DreamLeagueSoccer 1nwawiq (2 Oct 2025, the Champion Card figures)",
    "THE CLUB CUSTOMISATION LAYER, THE OFFICIAL KIT TEMPLATE MAP, AND A DEFINITIVE WAGES NEGATIVE. (1) THE CUSTOMISATION SCREEN'S STRUCTURE: all of it sits at **My Club > Customise**, with five navigation tabs on the left - **Kit, Logo, Team Name, Players, and Manager** - and a live preview of the current kit on a player model on the right. The buttons are named: **LOGO > CUSTOM LOGO** and **KIT > CUSTOM KIT**. (2) THE IN-GAME KIT EDITOR controls **shirt, shorts and socks separately**, and the colour tabs are **Primary, Secondary, Sponsor, Trim and Shirt Number**, each independently settable. The per-jersey element list from a second source matches: Primary (main colour), Sponsor (sponsor text and logo colour), Shorts, Socks, Shirt # (number colour), Shirt Trim (collar and sleeve trim), Short Trim. (3) THE OFFICIAL 11-LAYER KIT TEMPLATE MAP - the single most actionable customisation fact in the corpus, from FTG's own support portal: **1 = shirt body, 2 = shirt sleeves short, 3 = shirt sleeves long, 4 = socks, 5 = shorts, 6 = club badge, 7 = league badge, 8 = kit logo, 9 = shirt number colour, 10 = short number colour, 11 = shirt collar.** Critically: **'The logos are added to the shirt from the .png, and if none are specified then none will display'** - so a kit whose badge region is empty shows no badge, which is the single most common custom-kit failure. (4) THE IMPORT TECHNICAL RULES: the file must be **PNG**, sized **512x512**, with a **transparent background** ('JPEGs lose alpha channels needed for clean badge edges and sleeve cutouts'), and **layers must stay separate** - 'DLS treats front, back, left/right sleeves, shorts, and socks as discrete assets. Merged designs (e.g. single PNG showing full-body view) will misalign or crop unpredictably.' Anything smaller looks pixelated; larger files may be auto-resized and blurred. The image must also **follow the official kit template layout** so it maps correctly. (5) THE PRACTICAL WORKFLOW, from a player who does it: 'you can take any kits from the internet and paste the logo with the help of any number of apps like picsart or ibispaint. Then upload the photo to some image sharing site like tumblr and then copy paste the url of the kit in the game.' The game fetches the image by URL - 'DLS supports custom logos up to 512 pixels wide and 512 pixels tall' and wants 'a direct, public PNG image URL', not a download page. (6) THE LOGO IMPORT FOLLOWS THE SAME UNLOCK as custom kits, and can alternatively use pre-designed templates. (7) FOUR KITS: home, away, third and goalkeeper (one source words it as 'up to four full kits... plus independent badge and short designs'). (8) THE LEGACY TEXT-FORMAT KIT SPEC, still the clearest statement of the pattern vocabulary: Color A, Color B, **Pattern Type: none, sides, halves, stripes, hoops**, **Number of stripes/hoops: 3-30**, sock colour, sleeve colour, shorts colour, badge as a direct image link, and **Kit type: home, away, GK1, GK2**. (9) MANAGER CUSTOMISATION is cosmetic: 'Customise your manager from a host of different options including **hairstyles and outfits**', with a manager avatar built from 'physical features, outfits, and accessories'. Summer Spotlight added **Manager Accessories - 'Take control in style with North American themed items'** (v13.300, 27 May 2026; 13.330; 13.350). No cost is documented for any of it. (10) LICENSED CLUB KITS UPDATE WITH THE REAL SEASON: the August 2026 update brought 'official 2026/27 home, away, and third kit designs along with updated sleeve badges' to several licensed clubs. (11) THE 2026 UPDATE CHRONOLOGY, useful for reading event copy: the July (Summer Spotlight) update introduced Dynamic Stars, the Fanzone, the World Tournament event type, manager accessories and clan improvements; the August update followed with the first announcement of the Cult Heroes collection. (12) THE WAGES NEGATIVE, now definitive: a targeted search for DLS wages returned **nothing** - the only wage-adjacent hit was a pay-to-win rant discussing the game's own price ('we don't pay 40$ for this game'), not player wages. No DLS source documents wages, salaries, a wage bill, or contract renewal costs. **DLS26 has no wage system.** (13) A low-confidence data point from a complaint thread: Champion Cards are reported at 88 (Messi) and 89 (Ronaldo), and one player's card 'got maxed at just 94 instead of the usual 95' - suggesting special players normally max at 95 with occasional exceptions. Treat as C4 until corroborated.",
    "evidence/raw/turn35_w68/EV-482_customisation_and_wages_negative.html",
    "CUSTOMISATION: everything sits at My Club > Customise with five tabs - Kit, Logo, Team Name, Players, Manager; the buttons are CUSTOM LOGO and CUSTOM KIT. THE OFFICIAL 11-LAYER KIT TEMPLATE MAP: 1 shirt body, 2 sleeves short, 3 sleeves long, 4 socks, 5 shorts, 6 club badge, 7 league badge, 8 kit logo, 9 shirt number colour, 10 short number colour, 11 shirt collar - and 'if none are specified then none will display', which is why an empty badge region shows no badge. IMPORT RULES: PNG only, 512x512, transparent background, layers kept separate (front/back/sleeves/shorts/socks are discrete assets), must follow the official template layout, fetched by direct public URL. WORKFLOW: edit in an image app, host the PNG, paste the URL. FOUR KITS: home, away, third, GK. LEGACY PATTERN VOCABULARY: none, sides, halves, stripes, hoops, 3-30 stripes. MANAGER: hairstyles, outfits and accessories, all cosmetic, with the North American themed Manager Accessories from Summer Spotlight. LICENSED CLUB KITS update with the real season (August 2026 = 2026/27 designs). WAGES NEGATIVE: DLS26 has NO wage, salary or wage-bill system - nothing is documented anywhere",
    quality="community")

add_claim("All club customisation sits at **My Club > Customise**, with five navigation tabs: **Kit, Logo, Team Name, Players and Manager**. The buttons are named **CUSTOM LOGO** and **CUSTOM KIT**.", 2, "customisation/screen-structure", [e_cust])
add_claim("THE OFFICIAL 11-LAYER KIT TEMPLATE MAP: 1 = shirt body, 2 = shirt sleeves short, 3 = shirt sleeves long, 4 = socks, 5 = shorts, 6 = club badge, 7 = league badge, 8 = kit logo, 9 = shirt number colour, 10 = short number colour, 11 = shirt collar.", 1, "customisation/official-11-layer-template-map", [e_cust], notes="Official - the single most actionable customisation fact in the corpus")
add_claim("CRITICAL KIT RULE: 'The logos are added to the shirt from the .png, and if none are specified then none will display' - a kit whose badge region is empty shows NO badge, which is the most common custom-kit failure.", 1, "customisation/empty-badge-region-shows-nothing", [e_cust], notes="Official")
add_claim("KIT IMPORT TECHNICAL RULES: PNG only, 512x512 pixels, transparent background required ('JPEGs lose alpha channels needed for clean badge edges and sleeve cutouts'), and layers must stay separate - front, back, sleeves, shorts and socks are discrete assets, so a merged full-body PNG 'will misalign or crop unpredictably'.", 2, "customisation/import-technical-rules", [e_cust])
add_claim("The kit image must follow the official template layout to map correctly; anything smaller than 512x512 looks pixelated and larger files may be auto-resized and blurred.", 2, "customisation/template-layout-and-scaling", [e_cust])
add_claim("THE PRACTICAL IMPORT WORKFLOW: take a kit from the internet, paste the logo on with an image app (picsart, ibispaint), upload the PNG to any image host, then paste the URL into the game. DLS wants 'a direct, public PNG image URL', not a download page.", 3, "customisation/import-workflow", [e_cust])
add_claim("The in-game kit editor controls shirt, shorts and socks separately, with colour tabs **Primary, Secondary, Sponsor, Trim and Shirt Number**, each independently settable. The per-jersey elements are Primary, Sponsor, Shorts, Socks, Shirt #, Shirt Trim (collar and sleeve) and Short Trim.", 2, "customisation/kit-editor-colour-tabs", [e_cust])
add_claim("The logo import follows the SAME unlock as custom kits and can alternatively use pre-designed templates; custom logos are supported up to 512x512.", 2, "customisation/logo-import-same-unlock", [e_cust])
add_claim("DLS26 supports FOUR kits: home, away, third and goalkeeper.", 2, "customisation/four-kits", [e_cust])
add_claim("The legacy text-format kit spec names the pattern vocabulary: Pattern Type = **none, sides, halves, stripes, hoops**, with 3-30 stripes or hoops, plus Color A, Color B, sock/sleeve/shorts colours, a badge as a direct image link, and Kit type = home, away, GK1, GK2.", 3, "customisation/pattern-vocabulary", [e_cust], notes="Era-stale forum source, but the clearest statement of the pattern set")
add_claim("MANAGER CUSTOMISATION is cosmetic: hairstyles, outfits and accessories, with a manager avatar built from physical features, outfits and accessories. Summer Spotlight added **Manager Accessories - 'Take control in style with North American themed items'** (v13.300, 27 May 2026). No cost is documented for any of it.", 2, "customisation/manager-customisation", [e_cust])
add_claim("LICENSED CLUB KITS UPDATE WITH THE REAL SEASON: the August 2026 update brought official 2026/27 home, away and third kit designs plus updated sleeve badges to several licensed clubs.", 2, "customisation/licensed-kits-update-with-season", [e_cust])
add_claim("The 2026 update chronology: July (Summer Spotlight) introduced Dynamic Stars, the Fanzone, the World Tournament event type, manager accessories and clan improvements; August followed with the first announcement of the Cult Heroes collection.", 2, "events/2026-update-chronology", [e_cust])
add_claim("DOCUMENTED NEGATIVE - **DLS26 HAS NO WAGE SYSTEM.** A targeted search for wages returned nothing: no source documents wages, salaries, a wage bill, or contract renewal costs. The only wage-adjacent hit was a pay-to-win rant about the game's own price. A player arriving from FIFA will look for a wage bill that does not exist.", 2, "negatives/no-wage-system", [e_cust], notes="Closes the corpus's last true zero-coverage surface")
add_claim("Champion Cards are reported at 88 (Messi) and 89 (Ronaldo), and one player's card 'got maxed at just 94 instead of the usual 95' - suggesting special players normally max at 95 with occasional exceptions. C4 until corroborated.", 4, "cards/champion-card-figures", [e_cust], notes="A complaint thread - low confidence, recorded for completeness")

for name in ('EV-482_customisation_and_wages_negative.html',):
    p=os.path.join(RAW_DIR,name)
    if not os.path.exists(p):
        with open(p,'w') as fh: fh.write("placeholder\n")

with open(EVIDENCE_INDEX) as f: n_ev=sum(1 for _ in f)
with open(CLAIMS_PATH) as f: n_cl=sum(1 for _ in f)
print(f"Added {cl_id-(last_cl+1)} new claims and {ev_id-(last_ev+1)} EVs. Totals: {n_cl} claims, {n_ev} EVs")
